from pathlib import Path
from html import escape

ROOT = Path(__file__).resolve().parents[1] / 'site'
repo = 'https://github.com/OpenXeroth/acoustic-re-id-research'

def page(path, title, description, body, active='', script=False):
    links = [('/', 'NatureCam'), ('/acoustic-re-id-research/', 'Research'), ('/djuma-birds/', 'Djuma birds')]
    nav = ''.join(f'<a href="{u}"'+(' aria-current="page"' if n == active else '')+f'>{n}</a>' for u,n in links)
    content = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · OpenXeroth</title><meta name="description" content="{escape(description)}"><meta name="theme-color" content="#738878"><link rel="icon" href="/assets/xeroth-green.png"><link rel="canonical" href="https://open.xeroth.ai{path}"><meta property="og:title" content="{escape(title)} · OpenXeroth"><meta property="og:description" content="{escape(description)}"><link rel="stylesheet" href="/assets/site.css"></head><body><a class="skip" href="#main">Skip to content</a><header class="top"><div class="wrap"><div class="nav"><a class="brand" href="/" aria-label="OpenXeroth home"><img src="/assets/xeroth-green.png" alt="" width="40" height="40">Open<span>Xeroth</span></a><nav aria-label="Main navigation">{nav}<a class="nav-github" href="https://github.com/OpenXeroth">GitHub ↗</a></nav></div></div></header><main id="main" class="wrap">{body}</main><footer><div class="wrap footer-row"><div><a class="brand" href="/">Open<span>Xeroth</span></a><p>Open research. A closer connection to the wild.</p><span>NatureCam is part of <a href="https://xeroth.ai">Xeroth</a>.</span></div><div class="footer-links"><a href="https://www.youtube.com/@djumacam">Djuma Cam on YouTube ↗</a><a href="https://github.com/OpenXeroth">GitHub ↗</a><a href="https://www.djuma.com/djumacam">The Djuma story ↗</a></div></div></footer>{'<script type="module" src="/assets/birds.js"></script>' if script else ''}</body></html>'''
    p = ROOT / path.strip('/') / 'index.html';p.parent.mkdir(parents=True, exist_ok=True);p.write_text(content)

scene='''<div class="scene" role="img" aria-label="Illustration of the landscape around a waterhole, with an observation marker"><div class="scene-label">DJUMA · SOUTH AFRICA</div><svg viewBox="0 0 500 400" fill="none" aria-hidden="true"><circle cx="330" cy="88" r="48" fill="#f8f9ee"/><path d="M-20 250Q95 185 230 244T540 225V440H-20Z" fill="#ced9c1"/><path d="M-20 289Q105 225 255 280T530 265V420H-20Z" fill="#aabd9f"/><path d="M-20 335Q110 283 250 340T530 305V420H-20Z" fill="#8da389"/><path d="M200 352Q285 324 401 350Q470 369 504 398H93Q118 374 200 352" fill="#dce5d6"/><path d="M278 363L420 363M207 376H452M256 387H484" stroke="#aabd9f"/><path d="M84 317L95 154M94 212L66 181M93 205L122 174" stroke="#657f63" stroke-width="5"/><path d="M40 166Q49 133 83 142Q96 112 119 136Q153 125 163 159Q176 177 122 175Q79 188 40 166" fill="#6f8869"/><path d="M390 300L398 235M398 260L413 245" stroke="#718c6d" stroke-width="3"/><path d="M365 239Q376 217 393 225Q410 205 432 230Q444 247 412 246Z" fill="#7c9675"/><path d="M176 127l8-4 8 4M202 117l8-4 8 4" stroke="#728877" stroke-width="2"/></svg><div class="scene-cross"></div><div class="scene-chip"><strong>Observe. Listen. Learn.</strong>NatureCam research in progress</div><div class="scene-note">A WINDOW INTO THE WILD · SINCE 1998</div></div>'''
wave='<div class="wave" aria-hidden="true">'+''.join(f'<i style="height:{h}px"></i>' for h in [8,15,12,24,48,28,15,55,80,45,100,68,35,16,28,56,85,46,28,14,40,69,44,24,10,18,31,20,10])+'</div>'
page('/', 'A closer connection to the wild', 'NatureCam, Hosana, AI zoomies and open acoustic research from Xeroth. Explore the birds being detected at Djuma Cam.', f'''
<section class="hero"><div><div class="eyebrow">NatureCam by Xeroth</div><h1>A closer look.<br><em>A longer listen.</em></h1><p class="lead">Understanding wildlife begins with paying attention. We’re building tools that help people observe, recognise and learn from animals in the wild.</p><div class="actions"><a class="button" href="/djuma-birds/">Explore Djuma birds <span>↗</span></a><a class="button secondary" href="#naturecam">Meet NatureCam <span>↓</span></a></div></div>{scene}</section>
<div class="strip"><span><strong>Our starting point</strong> · Djuma Cam, South Africa</span><span><strong>Our approach</strong> · People + observation + AI</span><span><strong>Our work</strong> · Shared openly</span></div>
<section class="section" id="naturecam"><div class="eyebrow">01 / The NatureCam project</div><div class="section-title"><h2>From watching wildlife<br>to understanding it.</h2><p>NatureCam is Xeroth’s project to connect nature cameras, human expertise and AI. Djuma is where we’re starting—with the people who know this camera best.</p></div><div class="grid3"><article class="card"><span class="number">01 — OBSERVE</span><h3>A window that stays open</h3><p>Nature cameras let people return to the same place, day after day. Those patient observations reveal behaviours and patterns a single visit can miss.</p><a class="link" href="https://www.youtube.com/@djumacam">Watch Djuma Cam ↗</a></article><article class="card"><span class="number">02 — RECOGNISE</span><h3>Hosana: who came back?</h3><p>Hosana is the re-identification pipeline we’re building. Its goal is to connect repeat sightings of the same animal over time, starting at Djuma. Individual recognition is still being researched and validated.</p><span class="tag">In development</span></article><article class="card"><span class="number">03 — ASSIST</span><h3>An AI companion for zoomies</h3><p>Zoomies are the people who remotely pan, tilt and zoom nature cameras. We’re developing an AI zoomie to help them notice activity, follow animals and choose useful views, with human judgement at the centre.</p><span class="tag">In development</span></article></div><div class="history"><div class="year">1998</div><p>Djuma’s first webcam began sending still images in August 1998. Later that year it moved to overlook Gowrie Dam. A community of viewers and remote camera operators grew around this enduring window into the South African bush. <a href="https://www.djuma.com/djumacam">Read Djuma’s history ↗</a></p></div></section>
<section class="section"><div class="feature"><div class="signal"><div class="eyebrow">A question worth listening to</div>{wave}<h3>Same bird.<br>Or just the same background?</h3><div class="small"><span>VOICE · PLACE · RECORDING</span><span>ACOUSTIC RE-ID</span></div></div><div><div class="eyebrow">02 / Open research</div><h2>Can a voice tell us<br>who’s calling?</h2><p class="lead">Recognising a species is one thing. Recognising an individual animal is much harder.</p><p>Our acoustic re-identification research asks whether AI learns an animal’s voice—or shortcuts such as the microphone, background or recording session. We tested these questions across nine species.</p><a class="link" href="/acoustic-re-id-research/">Explore the research, paper and code ↗</a></div></div></section>
<section class="section"><div class="bird-banner"><div><div class="eyebrow">03 / Listen in at Djuma</div><h2>A soundscape, made visible.</h2><p>With BirdNET-Cloud, we’re identifying likely bird species in calls from Djuma Cam. Explore the latest detections, browse species and follow each call’s record. Open to everyone, with no login.</p><span class="fine">Automated species suggestions—not confirmed individual identities.</span></div><a class="button" href="/djuma-birds/">Meet the birds <span>↗</span></a></div></section>''', 'NatureCam')
page('/acoustic-re-id-research/','Does AI recognise the animal—or the recording?', 'Plain-English guide to our acoustic re-identification research, with the full paper, source code, dataset and model links.', f'''
<div class="subhero"><div class="breadcrumbs"><a href="/">OpenXeroth</a> / Acoustic re-identification</div><div class="eyebrow">Research / Author manuscript v7</div><h1>Whose voice<br><em>are we really hearing?</em></h1><p class="lead">A computer can appear to recognise an individual animal without learning its voice. It might recognise the place, the microphone or the recording instead. Our research tests how much that matters.</p><div class="actions"><a class="button" href="/papers/acoustic-re-id-v7.pdf">Read the full paper <span>↓ PDF</span></a><a class="button secondary" href="{repo}">Explore the code <span>↗</span></a></div></div><div class="stats"><div class="stat"><span class="big-number">9</span><small>species · eight birds and one bat</small></div><div class="stat"><span class="big-number">13</span><small>datasets evaluated</small></div><div class="stat"><span class="big-number">36 + 2</span><small>neural networks + simple controls</small></div></div>
<section class="section prose"><div class="eyebrow">The question</div><h2>Recognising the singer,<br>not just the song.</h2><p>Imagine recognising a friend on the phone. You want to recognise their voice whether they call from home, a busy street or a different handset. An animal-recognition system needs the same resilience.</p><p>Acoustic re-identification means trying to tell whether a call belongs to an animal encountered before. Species classification asks “what kind of bird is that?” Re-identification asks “is that the same bird?” A convincing answer could help us follow animals without having to see them every time.</p><p>But recordings carry more than a voice. If one animal is always recorded in one place, the background can become an accidental name tag.</p></section>
<section class="section"><div class="eyebrow">What we tested</div><h2>Four ways to check<br>what the computer learned.</h2><article class="finding"><span class="num">01</span><div><h3>Change the recording session.</h3><p>We compared results when recordings were mixed at random with results that kept sessions apart. In twelve matched comparisons across two species, random splitting raised accuracy by 19–51 percentage points. That can create a misleading impression of performance on a new day.</p></div></article><article class="finding"><span class="num">02</span><div><h3>Take the animal’s voice away.</h3><p>Could the system still predict the identity from background alone? For chiffchaff recordings within a year, accuracy was 73.7% from backgrounds versus 76.5% from calls. A high score can therefore be evidence about the recording context, not just the animal.</p></div></article><article class="finding"><span class="num">03</span><div><h3>Hold the microphone and recording constant.</h3><p>Where several animals shared a recording, we could ask whether the model distinguished them beyond that shared context. Of three datasets with this stronger test, only one zebra finch dataset gave clear evidence of identity information beyond the recording.</p></div></article><article class="finding"><span class="num">04</span><div><h3>Let strangers arrive.</h3><p>In nature, a caller may be an animal the system has never met. We calibrated a threshold on separate unfamiliar animals, aiming to accept no more than one in ten strangers. On wild datasets separated by session, the median rate of accepting and correctly naming familiar callers was at most 37%. The test-time stranger rate could still exceed the calibration target.</p></div></article><p class="fine">These are specific benchmark results, not forecasts of Djuma performance. See the paper for uncertainty intervals, dataset qualifications and the complete comparisons.</p></section>
<section class="section"><div class="feature"><div><div class="eyebrow">Why it matters</div><h2>Better tests.<br>More trustworthy tools.</h2></div><div><p>We found no neural network that won on every dataset. Choosing a different internal layer also changed the rankings. The useful lesson is to test the entire recognition process against the conditions it will actually face.</p><p>For NatureCam and Hosana, that means treating individual identity as a claim to validate. Today’s BirdNET-Cloud detections at Djuma are species suggestions. They do not establish how many individual birds are present.</p><div class="notice">The study uses existing published datasets. It does not use Djuma Cam audio as a benchmark or demonstrate a working individual bird recogniser at Djuma.</div></div></div></section>
<section class="section"><div class="eyebrow">Read, inspect, reproduce</div><h2>The work is here to explore.</h2><div class="paper-box"><span class="tag">Author manuscript · Version 7 · 2 October 2026</span><h3 style="margin-top:20px">Recording context and data splitting can inflate acoustic re-identification accuracy across species and studies</h3><p>Graham Wallington &amp; Jackie Lighten · Xeroth AI Limited</p><div class="actions"><a class="button" href="/papers/acoustic-re-id-v7.pdf">Full paper · PDF ↓</a><a class="button secondary" href="{repo}/blob/main/docs/supporting-information.md">Supporting information ↗</a></div><p style="margin-top:22px">This is an author manuscript, not a labelled peer-reviewed publication. The public code release does not yet include the private numerical evidence archive or a fresh end-to-end reproduction.</p></div><div class="grid3" style="margin-top:22px"><article class="card"><h3>Source code</h3><p>Analysis methods, model adapters, controls and software tests.</p><a class="link" href="{repo}">Open the public repository ↗</a></article><article class="card"><h3>Datasets &amp; models</h3><p>Original publishers, model registries and their separate licence terms.</p><a class="link" href="{repo}/blob/main/docs/datasets.md">Find the datasets ↗</a><br><a class="link" href="{repo}/blob/main/docs/models.md">Find the models ↗</a></article><article class="card"><h3>Reproducibility</h3><p>How to verify the software, source provenance and what a numerical rerun still requires.</p><a class="link" href="{repo}/blob/main/docs/reproduction.md">Read the reproduction guide ↗</a></article></div></section>''','Research')
for path,mode,title,lead in [('/djuma-birds/','feed','Who’s calling at Djuma?','A window into the birdsong around Gowrie Dam. Explore the latest species suggestions from Djuma Cam, in partnership with BirdNET-Cloud.'),('/djuma-birds/species/','species','A closer listen.','Explore this species’ detection history at Djuma Cam.'),('/djuma-birds/call/','call','One call. A moment in the bush.','An individual detection from Djuma Cam’s soundscape.')]:
    page(path,title,'Public BirdNET-Cloud species detections from Djuma Cam. Latest calls, species histories and individual detection records.',f'''<div id="birds-app" data-mode="{mode}"><div class="subhero"><div class="breadcrumbs"><a href="/">OpenXeroth</a> / <a href="/djuma-birds/">Djuma birds</a></div><div class="eyebrow">Djuma Cam × BirdNET-Cloud</div><h1 id="bird-title">{title}</h1><p class="lead" id="bird-lead">{lead}</p><div class="status" id="feed-status" role="status">Connecting to the detection feed…</div></div><div class="notice">These are automated species suggestions, not confirmed sightings or individual identities. Confidence is a model score, not the probability that a suggestion is correct. Times below are South African Standard Time (UTC+2).</div><div id="bird-content" aria-busy="true"><p class="loading">Loading the soundscape…</p></div></div><section class="section"><div class="prose"><h2>Listening is just the beginning.</h2><p>One bird may produce many detections, and more than one bird may be present in a clip. Detection totals are not counts of animals. The feed refreshes every 60 seconds; upstream processing and interruptions can delay new records.</p><p><a href="https://birdnetcloud.com/s/djuma-cam-b1610b">Visit Djuma on BirdNET-Cloud ↗</a> · <a href="https://www.youtube.com/@djumacam">Watch Djuma Cam ↗</a></p><a class="link" href="/acoustic-re-id-research/">Why recognising individuals is harder ↗</a></div></section>''','Djuma birds',True)
